<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import MarkdownIt from 'markdown-it';
import serviceGuide from '../../docs/service-configuration.md?raw';
import requestGuide from '../../docs/api-request-guide.md?raw';
import v2Guide from '../../docs/api-v2-guide.md?raw';
import pokemonExample from '../../docs/request_examples/poke_api.json?raw';

const markdown = new MarkdownIt({ html: false, linkify: true, typographer: true });
const path = ref(location.pathname), username = ref(''), password = ref(''), error = ref(''), loading = ref(false);
const docsTab = ref<'service' | 'consumption'>('service'), configQuery = ref(''), requestQuery = ref('');
const configuration = [['APP_URL','URL pública usada en links y cookies del navegador.'],['APP_PORT','Puerto de escucha y publicación de Docker Compose.'],['PLAYGROUND_USERNAME','Usuario único habilitado para entrar a la consola.'],['PLAYGROUND_PASSWORD','Contraseña del usuario; mantener sólo en .env.'],['http.address','Dirección de escucha; usa 0.0.0.0:${APP_PORT} en Compose.'],['http.publicBaseUrl','Base pública para links del servicio.'],['security.egress.upstreamAllowedOrigins','Destinos de proveedores: URL exacta, wildcard de subdominio o *.'],['security.egress.webhookAllowedOrigins','Destinos permitidos para webhooks.'],['security.egress.allowHTTPForDevelopment','Permite HTTP sólo para desarrollo explícito.']];
const requestFields = [['definition.version','Versión del lenguaje de grafos: 1.'],['definition.api.baseUrl','URL base común del proveedor.'],['definition.api.limits','Cuota declarada: requests, per y concurrency opcional.'],['definition.calls','Un nodo raíz o un arreglo de raíces independientes.'],['calls[].name','Nombre de salida único entre hermanos.'],['calls[].type','single para recurso; collection para lista.'],['calls[].select','Selector por puntos sobre el JSON de respuesta.'],['calls[].request.path','Path GET relativo; admite bindings de parent y ancestros.'],['calls[].children','Relaciones que enriquecen cada valor del nodo.'],['webhook','Notificación terminal opcional.']];
function matches(items: string[][], query: string) { const q=query.trim().toLowerCase(); return q ? items.filter(([n,d])=>`${n} ${d}`.toLowerCase().includes(q)) : items; }
const filteredConfiguration = computed(()=>matches(configuration,configQuery.value));
const filteredRequestFields = computed(()=>matches(requestFields,requestQuery.value));
const renderedService = computed(()=>markdown.render(serviceGuide));
const renderedConsumption = computed(()=>markdown.render(`${requestGuide}\n\n---\n\n${v2Guide}`));
async function login(){loading.value=true;error.value='';try{const r=await fetch('/playground/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});if(r.ok){location.assign('/playground');return}error.value=r.status===401?'Credenciales incorrectas.':'No se pudo iniciar sesión. Intenta nuevamente.'}catch{error.value='No se pudo conectar con el servicio.'}finally{loading.value=false}}
async function logout(){await fetch('/playground/api/session',{method:'DELETE'});location.assign('/login')}
function tryExample(){location.assign('/playground?example=pokemon')}
onMounted(async()=>{if(path.value!=='/login'&&!(await fetch('/playground/api/session')).ok)location.replace('/login')});
</script>

<template><main class="shell"><header><a href="/playground" class="brand">↳ API ENGINE <small>v2</small></a><nav v-if="path!=='/login'"><a href="/playground">Playground</a><a href="/docs">Docs</a><a href="/examples">Ejemplos</a><button @click="logout">Cerrar sesión</button></nav></header>
<section v-if="path==='/login'" class="login"><p class="eyebrow">CONSOLA DE EJECUCIÓN</p><h1>Inicia sesión.</h1><p>Accede al playground y a la documentación del motor.</p><form @submit.prevent="login"><label>Usuario<input v-model="username" autocomplete="username" required></label><label>Contraseña<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button :disabled="loading">{{loading?'Validando…':'Entrar al playground'}}</button></form></section>
<section v-else-if="path==='/docs'" class="documentation"><p class="eyebrow">DOCUMENTACIÓN INTERACTIVA</p><h1>Opera y consume API Engine.</h1><p class="lead">Consulta la guía completa y encuentra campos sin recorrer el documento manualmente.</p><div class="tabs" role="tablist"><button :class="{active:docsTab==='service'}" @click="docsTab='service'">Servicio y arranque</button><button :class="{active:docsTab==='consumption'}" @click="docsTab='consumption'">Consumo de grafos</button></div><div v-if="docsTab==='service'" class="doc-layout"><aside><h2>Configuración</h2><input v-model="configQuery" placeholder="Buscar propiedad…" aria-label="Buscar propiedad de configuración"><ul><li v-for="([name,description]) in filteredConfiguration" :key="name"><code>{{name}}</code><span>{{description}}</span></li></ul></aside><article class="markdown" v-html="renderedService"></article></div><div v-else class="doc-layout"><aside><h2>Request JSON</h2><input v-model="requestQuery" placeholder="Buscar parámetro…" aria-label="Buscar parámetro de request"><ul><li v-for="([name,description]) in filteredRequestFields" :key="name"><code>{{name}}</code><span>{{description}}</span></li></ul></aside><article class="markdown" v-html="renderedConsumption"></article></div></section>
<section v-else-if="path==='/examples'" class="documentation"><p class="eyebrow">EJEMPLOS</p><h1>PokéAPI · bosque con relaciones</h1><p class="lead">Obtiene el idioma español, los Pokémon de la Pokédex de Paldea y la especie de cada entrada.</p><div class="example-grid"><article><h2>Cómo leerlo</h2><p>Dos raíces independientes. <code>pokemon</code> selecciona <code>pokemon_entries</code>; su hijo usa <code>{parent.pokemon_species.name}</code> para resolver cada especie.</p><button @click="tryExample">Inténtalo en playground →</button></article><pre aria-label="Ejemplo JSON de PokéAPI">{{pokemonExample}}</pre></div></section><section v-else class="documentation"><h1>Abriendo playground…</h1></section></main></template>

<style>
:root{color-scheme:dark;font-family:Inter,system-ui,sans-serif;background:#080f20;color:#e4ebff}*{box-sizing:border-box}body{margin:0}.shell{min-height:100vh;background:radial-gradient(circle at 85% -20%,#16325a77,transparent 34rem),#080f20}header{height:58px;padding:0 max(18px,calc((100vw - 1280px)/2));display:flex;align-items:center;justify-content:space-between;background:#121b34;border-bottom:1px solid #1a2945}a{color:#c8d2e7;text-decoration:none}.brand{font-weight:800;letter-spacing:1.6px;color:#e4ebff}.brand small{padding:4px 6px;color:#85bff1;background:#1d2944;margin-left:8px}nav{display:flex;align-items:center;gap:18px}button{border:0;border-radius:3px;background:#4cdcb3;color:#071124;padding:11px 15px;font-weight:700;cursor:pointer}nav button{padding:7px 10px;background:#1d2944;color:#e4ebff}.documentation,.login{max-width:1280px;margin:0 auto;padding:54px 24px}.login{max-width:440px;padding-top:72px}.eyebrow{font:700 11px ui-monospace,monospace;letter-spacing:1px;color:#4cdcb3}h1{font-size:clamp(32px,5vw,50px);letter-spacing:-2px;margin:8px 0 10px}h2{margin:0 0 12px}.lead,p{line-height:1.65;color:#c4cce0}.lead{max-width:740px}.tabs{display:flex;gap:8px;margin:34px 0 18px;border-bottom:1px solid #263653}.tabs button{background:transparent;color:#9aa8c2;border-radius:0}.tabs button.active{color:#4cdcb3;border-bottom:2px solid #4cdcb3}.doc-layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:24px}.doc-layout aside{height:max-content;position:sticky;top:20px;padding:18px;background:#101a30;border:1px solid #263653}.doc-layout input,input{width:100%;border:1px solid #263653;background:#071124;color:#e4ebff;padding:12px;border-radius:3px}.doc-layout ul{padding:0;margin:16px 0 0;list-style:none;display:grid;gap:12px}.doc-layout li{display:grid;gap:4px;font-size:12px}.doc-layout li span{color:#9aa8c2}.markdown{min-width:0;padding:8px 24px;background:#0c1528;border:1px solid #1b2943}.markdown :deep(h1),.markdown :deep(h2),.markdown :deep(h3){margin:28px 0 12px;letter-spacing:-.5px}.markdown :deep(p),.markdown :deep(li){color:#c4cce0;line-height:1.7}.markdown :deep(pre),pre{overflow:auto;background:#071124;border:1px solid #263653;padding:16px;color:#68e9ff}.markdown :deep(code),code{color:#68e9ff}.markdown :deep(table){width:100%;border-collapse:collapse;display:block;overflow:auto}.markdown :deep(th),.markdown :deep(td){padding:9px;border:1px solid #263653;text-align:left}.example-grid{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.2fr);gap:24px;margin-top:28px}.example-grid article{padding:24px;background:#101a30;border:1px solid #263653}.example-grid pre{margin:0;max-height:620px}.error{color:#ff9a8b;margin:0}form{margin-top:30px;display:grid;gap:16px;padding:24px;background:#101a30;border:1px solid #263653}label{display:grid;gap:7px;color:#c8d2e7}@media(max-width:760px){header{padding:0 14px}.brand{font-size:12px}nav{gap:10px;font-size:12px}.documentation{padding:38px 16px}.doc-layout,.example-grid{grid-template-columns:1fr}.doc-layout aside{position:static}.markdown{padding:8px 16px}}
</style>
